import{z as s,x as i,o as r,c as d,q as A,j as t,D as e,d as a,s as n,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"ESG 的公司金融视角","description":"","frontmatter":{"title":"ESG 的公司金融视角","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cf-esg-corporate.md","filePath":"econ/cf-esg-corporate.md","lastUpdated":1791063341000}'),p={name:"econ/cf-esg-corporate.md"};function C(c,E,h,m,F,g){const o=i("Mermaid");return r(),d("div",null,[E[2]||(E[2]=A('<h1 id="esg-的公司金融视角" tabindex="-1">ESG 的公司金融视角 <a class="header-anchor" href="#esg-的公司金融视角" aria-label="Permalink to &quot;ESG 的公司金融视角&quot;">​</a></h1><div class="epigraph"><p>ESG 首先改写的是公司的目标函数，其次才是它的资本成本；把顺序颠倒，绿色就只是一张卖给投资者的门票。</p><footer>—— 据 Hart–Zingales 2017 与 Berg–Kölbel–Rigobon 2022 整理</footer></div><p><a href="/econ/cf-governance-empirical-deep">上一课</a>把内部治理的识别钉住：设计先于回归，指数是筛选器。治理的默认目标是股东财富；本课问的是目标函数本身能不能改。<a href="/econ/esg-theory">ESG 理论</a>已从定价侧钉了两条：ESG 首先改变谁的偏好进入目标，其次才可能改变 alpha；绿色资本成本下降是机制，不是免费午餐。本课把这两条翻译到企业决策侧：公司何时、为什么、以什么代价做 ESG。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>目标函数之争。Friedman 1970：经理的受托责任是股东价值，花股东的钱做善事是代理问题。Hart–Zingales 2017：当外部性大到市场不进入价格，股东福利不等于股东财富——股东也喝同样的水，此时经理应当在治理约束内响应股东福利。分歧不在「要不要做好事」，而在<strong>决策权配置</strong>：交给市场（消费者与投资者用脚投票）还是交给经理裁量。注意这与上一课的治理管道直接相连：目标函数的扩展等于改写经理的激励合同，改得越宽，监督越难——自由现金流问题（Jensen 1986）会换一身绿色外衣回来。</p><p><span class="marginnote">把两派分歧翻译成一句话：Friedman 说「经理是股东钱财的管家，只管赚钱」；Hart–Zingales 说「股东不只在乎钱，也在乎喝的水，经理应在股东授权下兼顾后者」。争的不是善不善，而是决策权——交给市场用脚投票，还是交给经理自由裁量。</span></p><h3 id="企业侧的决策账" tabindex="-1">企业侧的决策账 <a class="header-anchor" href="#企业侧的决策账" aria-label="Permalink to &quot;企业侧的决策账&quot;">​</a></h3><p>做 ESG 的三个理由各有可检验含义。门槛利率渠道：投资者绿色偏好压低绿色企业资本成本（Pástor–Stambaugh–Taylor 2021 的机制），好项目集合扩大——应看到绿色投资对折现率敏感。需求渠道：员工与顾客的偏好换成现金流——Edmans 2011 发现员工满意度高的公司组合长期跑赢，解释落在意外与需求侧。代理渠道：ESG 成为经理的舒适品或粉饰工具——应看到披露与实际脱钩。三个渠道方向不同，混在一起谈「ESG 有没有用」注定没有答案。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>度量是第一道闸。Berg–Kölbel–Rigobon 2022 汇总六家主流评级：两两相关只有约 0.5 上下，同期信用评级的相关约 0.99。任何用「评级上升」识别企业效应的设计，必须先声明用的是哪家的分数、为什么它的口径贴近你想测的渠道。识别上沿用上一课的纪律：把评级当筛选器，用外生的监管变化（披露规则、碳定价）推因果。企业侧报告的口径也应从分数转向行为：排放的实际路径、资本开支的绿色占比、劳资事件的记录——可验证的行为，而不是分数本身。</p><p><span class="marginnote">数字实例：两家评级机构给同一批公司的 ESG 分数，相关系数只有约 0.5——大致相当于「同一学生的语文和数学成绩」之间的相关，而信用评级的相关高达 0.99。所以引用「评级上调」当证据前，得先说明自己选了哪把尺、为什么这把尺贴近要测的渠道。</span></p>',11)),(r(),t(l,null,{default:e(()=>[n(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PREF%5B%22%E6%8A%95%E8%B5%84%E8%80%85%E4%B8%8E%E5%88%A9%E7%9B%8A%E7%9B%B8%E5%85%B3%E8%80%85%E5%81%8F%E5%A5%BD%22%5D%20--%3E%20COC%5B%22%E7%BB%BF%E8%89%B2%E8%B5%84%E6%9C%AC%E6%88%90%E6%9C%AC%E5%8F%98%E5%8C%96%22%5D%0A%20%20COC%20--%3E%20GATE%5B%22%E9%A1%B9%E7%9B%AE%E9%97%A8%E6%A7%9B%E5%88%A9%E7%8E%87%22%5D%0A%20%20GATE%20--%3E%20INV%5B%22%E7%BB%BF%E8%89%B2%E6%8A%95%E8%B5%84%E4%B8%8E%E8%BF%90%E8%90%A5%22%5D%0A%20%20INV%20--%3E%20DISC%5B%22%E6%8A%AB%E9%9C%B2%E4%B8%8E%E8%AF%84%E7%BA%A7%22%5D%0A%20%20DISC%20--%3E%20VERIFY%7B%22%E6%8A%AB%E9%9C%B2%E5%8F%AF%E4%BF%A1%3F%22%7D%0A%20%20VERIFY%20--%3E%7C%E6%98%AF%7C%20KEEP%5B%22%E5%81%8F%E5%A5%BD%E7%BB%B4%E6%8C%81%EF%BC%8C%E6%9C%BA%E5%88%B6%E5%BB%B6%E7%BB%AD%22%5D%0A%20%20VERIFY%20--%3E%7C%E5%90%A6%7C%20WASH%5B%22%E7%B2%89%E9%A5%B0%E4%BE%B5%E8%9A%80%E5%9D%87%E8%A1%A1%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("把 "),B("a",{href:"/econ/esg-theory"},"ESG 理论"),a("的均衡翻译到企业侧：偏好推低绿色资本成本，门槛利率下降，绿色投资增加；若偏好持续，资本成本优势会被竞争摊薄，均衡落在「绿色更便宜」而不是「绿色更赚钱」——这正是定价课「不是免费午餐」的企业侧镜像。缺口在披露可信性：评级混乱与粉饰使投资者无法区分真投入与故事，承诺的价值因此取决于验证技术——审计、监管披露、第三方核查。验证越便宜，门槛利率渠道越能兑现；验证越贵，均衡越偏向代理渠道，经理买舒服、投资者买叙事。")],-1)),(r(),t(l,null,{default:e(()=>[n(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%8A%95%E8%B5%84%E8%80%85%E7%BB%BF%E8%89%B2%E5%81%8F%E5%A5%BD%22%5D%20--%3E%20L%5B%22%E7%BB%BF%E8%89%B2%E8%B5%84%E6%9C%AC%E6%88%90%E6%9C%AC%E4%B8%8B%E9%99%8D%22%5D%0A%20%20L%20--%3E%20I%5B%22%E7%BB%BF%E8%89%B2%E9%A1%B9%E7%9B%AE%E8%B6%8A%E8%BF%87%E9%97%A8%E6%A7%9B%E5%88%A9%E7%8E%87%22%5D%0A%20%20I%20--%3E%20K%5B%22%E6%9B%B4%E5%A4%9A%E4%BC%81%E4%B8%9A%E6%B6%8C%E5%90%91%E7%BB%BF%E8%89%B2%E8%B5%9B%E9%81%93%22%5D%0A%20%20K%20--%3E%20E%5B%22%E7%AB%9E%E4%BA%89%E6%91%8A%E8%96%84%E6%88%90%E6%9C%AC%E4%BC%98%E5%8A%BF%22%5D%0A%20%20E%20--%3E%20EQ%5B%22%E5%9D%87%E8%A1%A1%EF%BC%9A%E7%BB%BF%E8%89%B2%E6%9B%B4%E4%BE%BF%E5%AE%9C%EF%BC%8C%E8%80%8C%E9%9D%9E%E6%9B%B4%E8%B5%9A%E9%92%B1%22%5D%0A%20%20V%7B%22%E9%AA%8C%E8%AF%81%E6%8A%80%E6%9C%AF%E4%BE%BF%E5%AE%9C%E5%90%97%3F%22%7D%20--%3E%7C%E6%98%AF%7C%20H%5B%22%E9%97%A8%E6%A7%9B%E5%88%A9%E7%8E%87%E6%B8%A0%E9%81%93%E5%85%91%E7%8E%B0%22%5D%0A%20%20V%20--%3E%7C%E5%90%A6%7C%20A%5B%22%E4%BB%A3%E7%90%86%E6%B8%A0%E9%81%93%E6%8A%AC%E5%A4%B4%EF%BC%9A%E4%B9%B0%E8%88%92%E6%9C%8D%E4%B9%B0%E5%8F%99%E4%BA%8B%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=A('<p><span class="marginnote">常见误区：以为「ESG 做得好＝股票回报高」。均衡里绿色资本成本更低，意味着投资者事先接受了更低的期望收益——便宜是结果，不是奖赏。把「绿色更便宜」读成「绿色更赚钱」，等于把打折商品当成捡漏信号。</span></p><p><span class="marginnote">Berg–Kölbel–Rigobon 2022 的分解：评级分歧约五成半来自度量口径、近四成来自权重、其余来自范围——同一家的分数变化，可能只是换了个加权，而不是公司变了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>ESG 不是 alpha 引擎：事后绿色收益依赖预期的实现路径，定价侧的结论照搬到企业侧会误事。披露不等于表现；评级相关低不等于评级都错——可能各自度量不同的东西。本课不写主权债与转型金融的定价细节，也不重复定价侧的均衡推导。企业侧最大的未决问题是治理化的目标函数：股东福利进合同后，谁来审计「福利」本身——这是上一课管道分析与本课目标的交集，留作开放问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ESG 先改目标函数，再谈资本成本：Friedman 与 Hart–Zingales 的分歧是决策权配置。</li><li>三条渠道（门槛利率、需求、代理）方向不同，必须分开检验。</li><li>评级相关性约 0.5 量级，度量是第一道闸；识别靠外生监管变化，分数只当筛选器。</li><li>均衡落在「绿色更便宜」而非「绿色更赚钱」；验证技术决定渠道走向。</li><li>出处：Friedman 1970；Jensen 1986；Hart–Zingales 2017；Edmans 2011；Pástor–Stambaugh–Taylor 2021；Berg–Kölbel–Rigobon 2022。</li></ul>',6))])}const S=s(p,[["render",C]]);export{f as __pageData,S as default};
